import {config} from './config.js';
import {getSavedGoals,getSavedSnapshot,loadLatest,loadGoals,persistGoals,refreshInsights,getSavedProfile,loadProfile} from './api.js';
import {createExperience} from './experience.js';
import {personalFeedback} from './personalization.js';
import {analyzeDay,analyzeSport,compareActivities,activityStats,localDate} from './analytics.js';

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',heart:'M20.5 4.6a5 5 0 0 0-7.1 0L12 6l-1.4-1.4a5 5 0 0 0-7.1 7.1L12 20l8.5-8.3a5 5 0 0 0 0-7.1Z',activity:'M2 12h5l3-7 4 14 3-7h5',menu:'M4 6h16M4 12h16M4 18h16',band:'M8 5V1h8v4M8 19v4h8v-4M7 5h10v14H7z',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',down:'m5 9 7 7 7-7',arrow:'M4 12h16m-6-6 6 6-6 6',moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z',run:'m9 6 4 2 3 5 5 1M13 8l-3 6-5 2M10 14l5 3v5M3 8l4 1 3-3M15 3h.01',soccer:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7l5 4-2 6H9l-2-6ZM12 3v4M3 9l4 2M5 18l4-1M19 18l-4-1M21 9l-4 2',spark:'m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4ZM20 2v4m-2-2h4',refresh:'M20 7v5h-5M4 17v-5h5M6 7A7 7 0 0 1 18 5l2 3M4 16l2 3a7 7 0 0 0 12-2',check:'m5 12 4 4L19 6',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M18 6 6 18',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M16 3h5v5',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 11h16',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',lungs:'M12 3v9M12 9c-3-6-5-4-7 1-2 5-2 10 2 9l3-2V9M12 9c3-6 5-4 7 1 2 5 2 10-2 9l-3-2V9',drop:'M12 3c-2 4-7 8-7 12a7 7 0 0 0 14 0c0-4-5-8-7-12Z',thermo:'M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0ZM12 8v9',bolt:'m13 2-9 12h7l-1 8 10-13h-7Z',edit:'m16 3 5 5-12 12-6 1 1-6ZM13 6l5 5',trend:'m3 17 6-6 4 4 8-12M15 3h6v6'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.activity}"/></svg>`;
const colors={sleep:'#aa9cff',recovery:'#48dfa7',effort:'#46b9ff',hrv:'#82b5d6',restingHr:'#aab9c7',stress:'#26d7a0',bodyBattery:'#6ee847'};
const metricNames={readiness:'Training readiness',sleepMinutes:'Sleep duration',sleepScore:'Sleep score',intensityMinutes:'Intensity minutes',hrv:'Heart rate variability',restingHr:'Resting heart rate',bodyBattery:'Body Battery',stress:'Stress',respiration:'Respiratory rate',pulseOx:'Blood oxygen',skinTemperature:'Skin temperature',steps:'Steps',calories:'Calories',vo2max:'VO₂ max',recoveryHours:'Recovery time',hrvStatus:'HRV status',trainingStatus:'Training status',napMinutes:'Naps',sleepNeedMinutes:'Sleep need',workoutBenefit:'Workout benefit',heartRate:'Heart rate'};
const units={hrv:'ms',restingHr:'bpm',heartRate:'bpm',respiration:'brpm',pulseOx:'%',skinTemperature:'°C from baseline',sleepMinutes:'min',sleepScore:'/100',readiness:'/100',bodyBattery:'/100',stress:'/100',intensityMinutes:'min',steps:'steps',calories:'kcal',vo2max:'ml/kg/min',recoveryHours:'h',napMinutes:'min'};
let profile=getSavedProfile();
let snapshot=getSavedSnapshot(),goals=getSavedGoals(),page='home',selectedDate=null,day=null,refreshing=false,period=7,trendMetric='hrv',selectedSport='Soccer',currentId=null,previousId=null,showAll=false,sportTrendMetric='loadPer60',focusBeforeDialog;
const demo=()=>config.mode==='demo';
const numeric=n=>typeof n==='number'&&Number.isFinite(n);
const num=(n,decimals=0)=>numeric(n)?Number(n.toFixed(decimals)).toLocaleString('en-US'):'—';
const signed=(n,suffix='',decimals=1)=>numeric(n)?`${n>0?'+':''}${num(n,decimals)}${suffix}`:'—';
const hm=n=>numeric(n)?`${Math.floor(Math.round(n)/60)}:${String(Math.round(n)%60).padStart(2,'0')}`:'—';
const longTime=n=>numeric(n)?`${Math.floor(Math.round(n)/60)}h ${Math.round(n)%60}m`:'—';
const valueUnit=(value,unit='',decimals=1)=>numeric(value)?`${num(value,decimals)}${unit}`:'—';
const dateLabel=(date,options={month:'short',day:'numeric'})=>{if(!date||!Number.isFinite(Date.parse(date)))return '—';const calendarDay=/^\d{4}-\d{2}-\d{2}$/.test(date);return new Intl.DateTimeFormat('en-US',{...options,timeZone:calendarDay?'UTC':snapshot?.timezone||'America/Panama'}).format(new Date(calendarDay?date+'T12:00:00Z':date));};
const timeLabel=d=>dateLabel(d,{hour:'numeric',minute:'2-digit'});
const shortTime=d=>dateLabel(d,{hour:'numeric',minute:'2-digit',hour12:true}).replace(' ','').toLowerCase();
const sportIcon=type=>type==='Soccer'?'soccer':type==='Run'?'run':'activity';
function refreshDay(){if(!snapshot){day=null;return;}selectedDate=selectedDate||localDate(snapshot.dataThrough,snapshot.timezone);day=analyzeDay(snapshot,goals,selectedDate);const available=snapshot.activities.filter(a=>localDate(a.date,snapshot.timezone)<=selectedDate);if(!available.some(a=>a.type===selectedSport))selectedSport=day.featuredSport||available[0]?.type||'Activity';}
function historyWindow(){const end=Date.parse(selectedDate+'T12:00:00Z'),rows=new Map(snapshot.history.map(row=>[row.date,row]));return Array.from({length:period},(_,i)=>{const date=new Date(end-(period-1-i)*86400000).toISOString().slice(0,10);return rows.get(date)||{date};});}
function metric(key){if(day?.day&&key in day.day)return day.day[key];if(day?.metrics&&key in day.metrics)return day.metrics[key];if(day?.health.metrics[key])return day.health.metrics[key].value;const m=snapshot?.metrics[key];return m?.status==='available'&&m.observedAt&&localDate(m.observedAt,snapshot.timezone)===selectedDate?m.value:null;}
function navigate(next){page=next;history.replaceState(null,'','#'+(next==='home'?'overview':next));render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function header(){const dates=day?.availableDates||[],index=dates.indexOf(selectedDate),today=localDate(new Date().toISOString(),snapshot?.timezone||'America/Panama');return `<header class="app-header"><div class="top-row"><button class="profile" data-page="more" aria-label="Personal settings">YOU</button><div class="date-switch" aria-label="Selected day"><button data-date-step="-1" ${index<=0?'disabled':''} aria-label="Previous day">${icon('back')}</button><button class="date-label" data-action="calendar" ${dates.length?'':'disabled'}>${selectedDate===today?'TODAY':dateLabel(selectedDate).toUpperCase()}</button><button data-date-step="1" ${index<0||index>=dates.length-1?'disabled':''} aria-label="Next day">${icon('chevron')}</button></div><button class="device-status" data-page="device" aria-label="Garmin device and data">${icon('band')}<i></i></button></div><div class="wordmark">CIRQA${demo()?'<span class="demo-badge">DEMO DATA</span>':''}</div></header>`;}
function nav(){const active=['health','sleep','recovery','effort','stress'].includes(page)?'health':['training','workout','history'].includes(page)?'training':['profile','goals','device','more','metrics'].includes(page)?'more':page;return `<nav class="nav-dock" aria-label="Main navigation"><div class="nav-pill">${[['home','Home','home'],['health','Health','heart'],['training','Training','activity'],['more','More','menu']].map(([id,label,i])=>`<button data-page="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</div><button class="insights-fab" data-page="insights" aria-label="Open your insights"><span>${icon('spark')}</span></button></nav>`;}
function refreshControl(){return `<div class="refresh-row"><span class="updated">${demo()?'Demo · ':''}${snapshot?'Updated '+timeLabel(snapshot.generatedAt):'Saved insights'}</span><button id="refresh" class="refresh-button" ${refreshing?'disabled aria-busy="true"':''}>${icon('refresh',refreshing?'spin':'')}${refreshing?'Refreshing…':'Refresh insights'}</button></div>`;}
function dial(value,progress,color,suffix=''){return `<div class="dial" style="--accent:${color};--length:${Math.min(100,Math.max(0,progress||0))*2.76}"><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="track" cx="50" cy="50" r="44"/><circle class="arc" cx="50" cy="50" r="44"/></svg><div class="dial-value">${numeric(value)?num(value):esc(value||'—')}${suffix?`<small>${suffix}</small>`:''}</div></div>`;}
function dials(){const recoveryKey=numeric(metric('readiness'))?'readiness':'bodyBattery';return `<div class="dials">${[['sleep','SLEEP',metric('sleepScore'),metric('sleepScore'),colors.sleep,'Sleep score',''],['recovery','BODY BATTERY',metric(recoveryKey),metric(recoveryKey),colors.recovery,recoveryKey==='readiness'?'Training readiness':'Body Battery',''],['effort','ACTIVITY',metric('intensityMinutes'),numeric(metric('intensityMinutes'))?100:0,colors.effort,'Intensity minutes','m']].map(([view,label,v,p,c,source,suffix])=>`<button class="dial-button" data-page="${view}" aria-label="${source}: ${v??'unavailable'}${suffix}">${dial(v,p,c,suffix)}<span class="dial-label">${label}${icon('chevron')}</span><span class="dial-source">${source}</span></button>`).join('')}</div>`;}
function insightCard(insight,{compact=false,label='',click=true}={}){if(!insight)return '';return `<${click?'button':'article'} class="card insight-card" ${click?`data-insight="${esc(insight.id)}"`:''}>${label?`<span class="insight-label">${esc(label)}</span>`:''}<h3>${esc(insight.title)}</h3>${click?icon('chevron','insight-arrow'):''}<p>${esc(insight.body)}</p>${!compact&&insight.action?`<div class="action">${icon('arrow')}<span>${esc(insight.action)}</span></div>`:''}</${click?'button':'article'}>`;}
function monitors(){const h=day.health,keys=['hrv','restingHr','respiration'],ready=keys.filter(k=>h.metrics[k]?.sufficient&&h.metrics[k]?.value!=null),near=ready.filter(k=>h.metrics[k].position==='within-typical');const stress=metric('stress');return `<div class="monitors"><button class="monitor" data-page="health"><span class="monitor-heading">HEALTH MONITOR ${icon('chevron')}</span><span class="monitor-value"><span class="square">${icon('check')}</span><span><strong>${ready.length?`${near.length}/${ready.length} NEAR BASELINE`:'BUILDING BASELINE'}</strong><small>${ready.length?'Your personal history':'More recorded days needed'}</small></span></span></button><button class="monitor" data-page="stress"><span class="monitor-heading">STRESS MONITOR ${icon('chevron')}</span><span class="monitor-value"><span class="square">${num(stress)}</span><span><strong>${numeric(stress)?'DAILY AVERAGE':'NOT RECORDED'}</strong><small>${numeric(stress)?'Garmin score · 0–100':'No source reading'}</small></span></span></button></div>`;}
function activityRow(activity){const stats=activityStats(activity),color=colors.effort;return `<button class="activity-row" data-workout="${esc(activity.id)}" style="--accent:${color}"><span class="activity-score">${icon(sportIcon(activity.type))}${num(stats.durationMinutes)}<small>m</small></span><span class="activity-name">${esc(activity.type)}<small>${esc(activity.benefit==='Not provided'?'Recorded workout':activity.benefit.replaceAll('_',' ').toLowerCase())}</small></span><span class="activity-time">${shortTime(activity.date)}<br>${activity.endAt?shortTime(activity.endAt):shortTime(new Date(Date.parse(activity.date)+activity.durationSec*1000).toISOString())}</span></button>`;}
function dailyActivities(){const sleep=day.sleep;return `<section class="card activity-card"><div class="mini-heading"><span>${selectedDate===localDate(new Date().toISOString(),snapshot.timezone)?"TODAY’S ACTIVITIES":dateLabel(selectedDate).toUpperCase()+' ACTIVITIES'}</span><button data-page="training" aria-label="Open activity history">${icon('activity')}</button></div>${sleep.durationMinutes!=null?`<button class="activity-row" data-page="sleep" style="--accent:${colors.sleep}"><span class="activity-score">${icon('moon')}${hm(sleep.durationMinutes)}</span><span class="activity-name">SLEEP<small>Score ${num(sleep.score)}</small></span><span class="activity-time">${shortTime(sleep.start)}<br>${shortTime(sleep.end)}</span></button>`:''}${day.activities.map(activityRow).join('')}${!day.activities.length?'<p class="empty-note">No workouts recorded for this day.</p>':''}</section>`;}
function pairBars(rows,{max=100,unit='%'}={}){return `<div class="pair-bars">${rows.map(({label,value,color})=>`<div class="pair-bar"><span>${esc(label)}</span><div class="pair-track"><i style="--accent:${color};width:${numeric(value)?Math.min(100,Math.max(0,value/max*100)):0}%"></i></div><strong>${num(value,1)}${numeric(value)?unit:''}</strong></div>`).join('')}</div>`;}
function featuredSport(){const c=day.featuredComparison;if(!c?.current)return '';const d=c.deltas,s=c.currentStats,p=c.previousStats;return `<div class="section-heading"><h2>${esc(c.current.type)} progress</h2><button data-open-sport="${esc(c.current.type)}">View all ${icon('chevron')}</button></div><section class="card soccer-card"><div class="card-head"><div><h2>LAST SESSION VS PREVIOUS</h2><p>${dateLabel(c.current.date,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}${c.previous?' vs '+dateLabel(c.previous.date,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):''}</p></div>${icon(sportIcon(c.current.type))}</div><div class="comparison-hero"><div><div class="comparison-number">${signed(d.loadPer60Pct,'',0)}<small>${numeric(d.loadPer60Pct)?'%':''}</small></div><p class="comparison-caption">Training load per hour</p></div><span class="change-tag">${signed(d.anaerobicEffect,' anaerobic',1)}</span></div><p class="comparison-why">${p?`Garmin load per hour was ${num(s.loadPer60,1)} vs ${num(p.loadPer60,1)}. That separates workout intensity from time spent training.`:'An earlier session is needed to compare changes.'}</p>${pairBars([{label:'Latest',value:s.highSharePct,color:colors.effort},{label:'Previous',value:p?.highSharePct,color:'#7593a8'}])}<div class="data-note" style="padding-top:0">Zones 4–5 as a share of the full session</div><button class="card-link" data-workout="${esc(c.current.id)}">See what changed ${icon('chevron')}</button></section>`;}
function progressRow(label,current,target,color){return `<div class="goal-name"><b>${label}</b><span>${num(current,1)} / ${num(target,1)}</span></div><div class="goal-progress" role="progressbar" aria-label="${label}" aria-valuenow="${numeric(current)?Math.min(current,target):0}" aria-valuemin="0" aria-valuemax="${target}" aria-valuetext="${num(current,1)} of ${num(target,1)}"><i style="width:${numeric(current)?Math.min(100,current/target*100):0}%;background:${color}"></i></div>`;}
function planCard(){return `<div class="section-heading"><h2>My Plan</h2><button data-page="goals">Edit ${icon('edit')}</button></div><section class="card plan-card"><p class="goal-sub">${esc(goals.primary)}</p>${progressRow('Weekly workouts',day.week.sessions,goals.workoutsPerWeek,colors.effort)}${progressRow('Intensity minutes',day.week.intensityMinutes,goals.weeklyIntensityMinutes||150,colors.effort)}${progressRow('Sleep · hours',day.sleep.durationMinutes==null?null:day.sleep.durationMinutes/60,goals.sleepHours,colors.sleep)}</section>`;}

// SVGs use source observations only. Missing values and long time gaps break lines.
function lineChart(points,{color=colors.sleep,unit='',min=null,max=null,id='chart',area=false,timeSeries=false}={}){
  const valid=points.filter(p=>numeric(p.value));if(!valid.length)return '<p class="empty-note">No recorded values for this view.</p>';
  const lo=min??Math.max(0,Math.floor((Math.min(...valid.map(p=>p.value))-5)/5)*5),hi=max??Math.ceil((Math.max(...valid.map(p=>p.value))+5)/5)*5,range=Math.max(1,hi-lo);
  const p=points.map((point,index)=>({...point,x:32+(timeSeries?(point.time-points[0].time)/Math.max(1,points.at(-1).time-points[0].time):index/Math.max(1,points.length-1))*310,y:142-(point.value-lo)/range*118}));
  let draw='';for(let i=0;i<p.length;i++){const v=p[i];if(!numeric(v.value))continue;const gap=i>0&&timeSeries&&v.time-p[i-1].time>5*60000;draw+=`${i&&numeric(p[i-1].value)&&!gap?'L':'M'}${v.x.toFixed(2)},${v.y.toFixed(2)} `;}
  const ticks=[lo,(lo+hi)/2,hi];const labelIndices=[...new Set([0,Math.floor((p.length-1)/2),p.length-1])];
  return `<div class="chart-wrap"><svg viewBox="0 0 360 174" role="img" aria-label="${esc(id)}. ${valid.length} recorded values. Explore a point for details."><defs><linearGradient id="shade-${id}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="${color}" stop-opacity=".2"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>${ticks.map(t=>`<line class="chart-grid" x1="32" x2="345" y1="${142-(t-lo)/range*118}" y2="${142-(t-lo)/range*118}"/><text class="chart-label" x="2" y="${145-(t-lo)/range*118}">${num(t)}</text>`).join('')}${area&&!draw.includes(' M')?`<path d="${draw}L${p.at(-1).x},143 L${p[0].x},143 Z" fill="url(#shade-${id})"/>`:''}<path class="animated-line" pathLength="1" d="${draw}" stroke="${color}" stroke-width="1.8" fill="none" stroke-linejoin="round" stroke-linecap="round"/>${p.map((v,i)=>numeric(v.value)?`<g data-chart-point="${esc(v.tooltip||`${v.label} · ${num(v.value,1)} ${unit}`)}" data-readout="${id}" tabindex="0" role="button" aria-label="${esc(v.tooltip||`${v.label}, ${num(v.value,1)} ${unit}`)}"><circle class="chart-point" cx="${v.x}" cy="${v.y}" r="${points.length>40?1.2:2.7}" fill="${color}"/><circle class="chart-point-target" cx="${v.x}" cy="${v.y}" r="${points.length>40?4:7}"/></g>`:'').join('')}${labelIndices.map(i=>`<text class="chart-label" x="${p[i].x}" y="164" text-anchor="${i===0?'start':i===p.length-1?'end':'middle'}">${esc(p[i].label)}</text>`).join('')}</svg></div><div class="chart-readout" id="readout-${id}">Touch or focus the chart to explore.</div>`;
}
function barsChart(points,{color=colors.effort,unit='min',id='bars'}={}){const valid=points.filter(p=>numeric(p.value));if(!valid.length)return '<p class="empty-note">No recorded values.</p>';const max=Math.max(...valid.map(p=>p.value),1)*1.12,width=300/Math.max(1,points.length);return `<div class="chart-wrap"><svg viewBox="0 0 360 177" role="img" aria-label="${esc(id)} chart">${[0,.5,1].map(r=>`<line class="chart-grid" x1="31" x2="343" y1="${145-r*115}" y2="${145-r*115}"/><text class="chart-label" x="2" y="${148-r*115}">${num(r*max)}</text>`).join('')}${points.map((p,i)=>`<g tabindex="0" role="button" data-chart-point="${esc(p.tooltip||`${p.label} · ${num(p.value,1)} ${unit}`)}" data-readout="${id}" aria-label="${esc(p.tooltip||`${p.label}, ${num(p.value,1)} ${unit}`)}">${numeric(p.value)?`<rect x="${36+i*width}" y="${145-p.value/max*115}" width="${Math.max(2,width-6)}" height="${Math.max(1,p.value/max*115)}" rx="2" fill="${color}" opacity="${i===points.length-1?1:.68}"/>`:''}<rect x="${33+i*width}" y="25" width="${width}" height="122" fill="transparent"/>${points.length<9||i===0||i===points.length-1||i===Math.floor(points.length/2)?`<text class="chart-label" text-anchor="middle" x="${36+i*width+(width-6)/2}" y="164">${esc(p.label)}</text>`:''}</g>`).join('')}</svg></div><div class="chart-readout" id="readout-${id}">Touch or focus a session to see its value.</div>`;}
function periods(){return `<div class="period-switch" aria-label="Chart range"><button data-period="7" aria-pressed="${period===7}" class="${period===7?'active':''}">7d</button><button data-period="28" aria-pressed="${period===28}" class="${period===28?'active':''}">28d</button><button data-period="90" aria-pressed="${period===90}" class="${period===90?'active':''}">90d</button></div>`;}
function trendCard({key=trendMetric,tabs=true}={}){
  const selected=historyWindow(),points=selected.map(h=>({date:h.date,label:dateLabel(h.date,period===7?{weekday:'short'}:{month:'short',day:'numeric'}),value:h.date===selectedDate?metric(key):h[key],tooltip:dateLabel(h.date)+' · '+num(h.date===selectedDate?metric(key):h[key],1)+' '+(units[key]||'')})),valid=points.filter(p=>numeric(p.value));const avg=valid.length?valid.reduce((n,p)=>n+p.value,0)/valid.length:null;const b=day.health.metrics[key];let interpretation=b?.sufficient&&numeric(b.value)?`Selected day ${num(b.value,1)} ${units[key]||''}; your earlier ${b.count}-day median is ${num(b.baseline,1)}. ${signed(b.delta,' '+(units[key]||''))} versus that baseline.`:`${valid.length} recorded days in this view.`;
  if(key==='bodyBattery')interpretation='Each point is the latest recorded Body Battery for that day. Times differ; this is not a matched-time recovery comparison.';
  return `<section class="card trend-card" style="--accent:${colors[key]||colors.sleep}"><div class="card-head"><div><h2>${metricNames[key]||key}</h2><p>Last ${period} days</p></div>${periods()}</div>${tabs?`<div class="metric-tabs">${[['hrv','HRV'],['restingHr','Resting HR'],['sleepScore','Sleep'],['bodyBattery','Body Battery']].map(([k,label])=>`<button data-trend="${k}" class="${key===k?'active':''}">${label}</button>`).join('')}</div>`:''}<div class="chart-summary"><div><div class="chart-big">${num(avg,1)}<small>${units[key]||''}</small></div><div class="mini">${valid.length}-day average</div></div>${b?.sufficient&&numeric(b.value)&&key!=='bodyBattery'?`<span class="change-tag">${signed(b.delta,' '+(units[key]||''))} this day</span>`:''}</div>${lineChart(points,{id:'trend-'+key,color:colors[key]||colors.sleep,unit:units[key]||'',min:['bodyBattery','sleepScore','stress','readiness'].includes(key)?0:null,max:['bodyBattery','sleepScore','stress','readiness'].includes(key)?100:null})}<p class="chart-insight">${esc(interpretation)}</p></section>`;
}
function publishedRecommendations(){return day?.isLatestDay&&snapshot.goalsVersion===goals.version?snapshot.recommendations.filter(r=>r.source==='ai'||r.source==='grok'||(demo()&&r.source==='demo-rule')):[];}
function home(){return `<div class="home-layout"><section class="home-primary">${dials()}${refreshControl()}${insightCard(publishedRecommendations()[0]||day.primaryInsight,{compact:true,label:publishedRecommendations()[0]?(demo()?'DEMO RECOMMENDATION':'AI · YOUR PLAN'):day.featuredSport?day.featuredSport+' · LAST SESSION':''})}${monitors()}<div class="section-heading"><h2>My Day</h2><button data-page="insights" aria-label="See daily insights">${icon('plus')}</button></div><button class="section-link" data-page="insights"><span>${icon('spark')}Your daily outlook</span>${icon('chevron')}</button>${dailyActivities()}</section><section class="home-secondary">${featuredSport()}${planCard()}<div class="section-heading"><h2>My Dashboard</h2><button data-action="baseline-info">${icon('info')}</button></div>${trendCard()}</section></div>`;}
function pageTitle(title,back='home'){return `<div class="page-title"><button class="back-button" data-page="${back}" aria-label="Back">${icon('back')}</button><h1>${title}</h1><button class="icon-button" data-action="about" aria-label="About this data">${icon('info')}</button></div>`;}
function latestHrSamples(){return (snapshot.heartRateSeries||[]).filter(p=>numeric(p.bpm)&&localDate(p.timestamp,snapshot.timezone)===selectedDate).sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp));}
function workoutHrSamples(activity){const start=Date.parse(activity.date),end=activity.endAt?Date.parse(activity.endAt):start+activity.durationSec*1000;return (activity.heartRateSamples??snapshot.heartRateSeries??[]).filter(p=>numeric(p.bpm)&&Date.parse(p.timestamp)>=start&&Date.parse(p.timestamp)<=end).sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp));}
function heartChart(activity=null){const samples=activity?workoutHrSamples(activity):latestHrSamples();const latest=samples.at(-1);return `<section class="card trend-card hr-chart"><div class="card-head"><div><h2>${activity?'RECORDED HEART RATE':'HEART RATE'}</h2><p>${activity?'During this session':latest?'Last sample · '+timeLabel(latest.timestamp):'No samples for this day'}</p></div>${icon('heart')}</div><div class="chart-summary"><div><div class="chart-big">${num(activity?activity.avgHr:latest?.bpm)}<small>bpm</small></div><div class="mini">${activity?'Session average':'Latest recorded sample'}</div></div></div>${samples.length?lineChart(samples.map(p=>({time:Date.parse(p.timestamp),value:p.bpm,label:shortTime(p.timestamp),tooltip:timeLabel(p.timestamp)+' · '+p.bpm+' bpm'})),{id:activity?'workout-hr':'health-hr',color:colors.effort,unit:'bpm',area:true,timeSeries:true}):'<p class="empty-note">No recorded samples available for this view.</p>'}<div class="data-note">${samples.length?`${samples.length} recorded all-day samples · gaps remain gaps.`:'Historical activity summaries do not always include a heart-rate trace.'}</div></section>`;}
function healthTile(key){const b=key==='bodyBattery'?null:day.health.metrics[key],value=key==='heartRate'?latestHrSamples().at(-1)?.bpm:metric(key),isNumber=numeric(value),near=b?.position==='within-typical';return `<button class="health-tile" data-metric="${key}"><h2>${icon({respiration:'lungs',pulseOx:'drop',skinTemperature:'thermo',hrv:'activity',restingHr:'heart',bodyBattery:'bolt'}[key]||'activity')}${metricNames[key]}</h2><div class="health-value">${num(value,1)}<small>${isNumber?units[key]||'':''}</small></div><span class="baseline-tag ${!isNumber||!b?.sufficient?'neutral':near?'':'amber'}">${!isNumber?'Not recorded':b?.sufficient?`${signed(b.delta,' '+(units[key]||''))} vs baseline`:'Recorded source value'}</span>${isNumber&&b?.sufficient?`<div class="range-indicator"><i></i><b style="left:${Math.min(96,Math.max(2,25+(value-b.rangeLow)/Math.max(1,b.rangeHigh-b.rangeLow)*50))}%"></b></div>`:''}</button>`;}
function health(){return `${pageTitle('HEALTH MONITOR')}<div class="health-layout"><section>${heartChart()}</section><section><div class="health-grid">${['respiration','pulseOx','restingHr','hrv','skinTemperature','bodyBattery','stress','calories'].map(healthTile).join('')}</div><p class="subtle-note">Changes compare with your own previous observations. Your personal baseline is not a medical reference range.</p></section><section>${trendCard({key:'hrv',tabs:false})}</section><section>${insightCard(day.health.primaryInsight,{compact:false,click:false})}</section></div>`;}
function sleep(){const s=day.sleep;const stages=s.stages;const total=stages?Object.values(stages).reduce((n,v)=>n+(v||0),0):0;return `${pageTitle('SLEEP')}<div class="two-col"><section><div class="detail-main">${dial(s.score,s.score,colors.sleep)}<h2>SLEEP SCORE</h2><p>Garmin · ${dateLabel(selectedDate)}</p></div><div class="detail-stat-row"><div class="detail-stat"><strong>${hm(s.durationMinutes)}</strong><span>TIME ASLEEP</span></div><div class="detail-stat"><strong>${num(s.efficiencyPct,1)}<small>%</small></strong><span>CALCULATED EFFICIENCY</span></div><div class="detail-stat"><strong>${num(s.restorativeMinutes)}<small>m</small></strong><span>DEEP + REM</span></div></div><section class="card"><div class="card-head"><h2>SLEEP STAGES</h2>${icon('moon')}</div><div class="card-body">${stages?`<div class="sleep-band" role="img" aria-label="Recorded sleep stage durations">${[['deep','#6589a8'],['rem','#8bb1d0'],['light','#c2d5e3'],['awake','#5d6b76']].map(([key,color])=>`<i style="--accent:${color};flex:${stages[key]||0}" title="${key}: ${longTime(stages[key])}"></i>`).join('')}</div><div class="sleep-time"><span>${shortTime(s.start)}</span><span>${shortTime(s.end)}</span></div><div class="stage-list">${[['Deep','deep','#6589a8'],['REM','rem','#8bb1d0'],['Light','light','#c2d5e3'],['Awake','awake','#5d6b76']].map(([label,key,color])=>`<div><label><i style="--accent:${color}"></i>${label}</label><strong>${longTime(stages[key])}<small>${num(stages[key]/total*100)}%</small></strong></div>`).join('')}</div>`:'<p class="empty-note">Sleep stages were not recorded.</p>'}</div><div class="data-note">Stage totals as a share of recorded time in bed. Efficiency = sleep time ÷ time in bed.</div></section></section><section>${experience.sleepExtras()}${trendCard({key:'sleepMinutes',tabs:false})}<div class="detail-action">${icon('moon')}<div><h3>${s.recordedNights?`${s.nightsAtGoal} of ${s.recordedNights} nights met your goal`:'Your nightly target'}</h3><p>Your target is ${goals.sleepHours} hours. ${numeric(s.bedtimeVariabilityMinutes)?`Bedtime variability was ${num(s.bedtimeVariabilityMinutes,1)} minutes across ${s.timingNights} recorded nights.`:'Record at least three nights to compare bedtime consistency.'}</p></div></div><div class="insight-stack">${s.insights.map(i=>insightCard(i,{click:false})).join('')}</div></section></div>`;}
function recovery(){const key=numeric(metric('readiness'))?'readiness':'bodyBattery',value=metric(key);return `${pageTitle('RECOVERY')}<div class="two-col"><section><div class="detail-main">${dial(value,value,colors.recovery)}<h2>${metricNames[key].toUpperCase()}</h2><p>${key==='bodyBattery'?'Recorded energy reserve · Garmin 0–100':'Garmin training readiness'}</p></div><div class="health-grid">${['hrv','restingHr','respiration','stress'].map(healthTile).join('')}</div>${insightCard(day.health.primaryInsight,{click:false})}</section><section>${experience.bodyBatteryChart()}${trendCard({key:'hrv',tabs:false})}${trendCard({key:'restingHr',tabs:false})}</section></div>`;}
function effort(){const pts=historyWindow();return `${pageTitle('EFFORT')}<div class="two-col"><section><div class="detail-main">${dial(metric('intensityMinutes'),numeric(metric('intensityMinutes'))?100:0,colors.effort,'m')}<h2>INTENSITY MINUTES</h2><p>Moderate minutes + 2 × vigorous minutes</p></div><div class="detail-stat-row"><div class="detail-stat"><strong>${num(metric('steps'))}</strong><span>STEPS</span></div><div class="detail-stat"><strong>${num(metric('calories'))}</strong><span>CALORIES</span></div><div class="detail-stat"><strong>${num(day.week.intensityMinutes)}<small>m</small></strong><span>THIS WEEK</span></div></div>${dailyActivities()}</section><section><div class="card trend-card"><div class="card-head"><h2>INTENSITY MINUTES</h2>${periods()}</div>${barsChart(pts.map(h=>({label:dateLabel(h.date,{weekday:'short'}),value:h.intensityMinutes,tooltip:dateLabel(h.date)+' · '+num(h.intensityMinutes)+' intensity minutes'})),{id:'intensity-history'})}<p class="chart-insight">${num(day.week.intensityMinutes)} intensity minutes this week against your ${goals.weeklyIntensityMinutes||150}-minute goal. This measures recorded activity, not a WHOOP strain score.</p></div>${featuredSport()}</section></div>`;}
function stress(){return `${pageTitle('STRESS')} ${experience.stressDetails()}<div class="two-col"><section><div class="detail-main">${dial(metric('stress'),metric('stress'),colors.stress)}<h2>DAILY AVERAGE STRESS</h2><p>Garmin 0–100 scale · ${dateLabel(selectedDate)}</p></div>${insightCard(day.health.insights.find(i=>i.id.includes('stress'))||day.health.primaryInsight,{click:false})}<p class="subtle-note">This daily average uses Garmin’s stress measurement. It is not WHOOP’s 0–3 stress scale.</p></section><section>${trendCard({key:'stress',tabs:false})}</section></div>`;}
function sportPills(){const types=[...new Set(snapshot.activities.filter(a=>localDate(a.date,snapshot.timezone)<=selectedDate).map(a=>a.type))];types.sort((a,b)=>a===day.featuredSport?-1:b===day.featuredSport?1:a.localeCompare(b));return `<div class="sport-pills" aria-label="Sport">${types.map(type=>`<button data-sport="${esc(type)}" class="${type===selectedSport?'active':''}" aria-pressed="${type===selectedSport}">${esc(type)}</button>`).join('')}</div>`;}
function sportChart(data){const options={loadPer60:['LOAD PER HOUR','load/h'],highSharePct:['HIGH-INTENSITY SHARE','%'],durationMinutes:['SESSION DURATION','min']};const[label,unit]=options[sportTrendMetric];const values=data.trend.map(a=>({label:dateLabel(a.date),value:a[sportTrendMetric],tooltip:dateLabel(a.startedAt,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' · '+num(a[sportTrendMetric],1)+' '+unit}));const vals=values.filter(p=>numeric(p.value));const avg=vals.length?vals.reduce((n,p)=>n+p.value,0)/vals.length:null;return `<section class="card trend-card"><div class="card-head"><div><h2>${label}</h2><p>${data.summary.sessions} ${esc(selectedSport.toLowerCase())} sessions · last ${period} days</p></div>${periods()}</div><div class="metric-tabs">${[['loadPer60','Load / hour'],['highSharePct','Zones 4–5'],['durationMinutes','Duration']].map(([key,label])=>`<button data-sport-trend="${key}" class="${sportTrendMetric===key?'active':''}">${label}</button>`).join('')}</div><div class="chart-summary"><div><div class="chart-big">${num(avg,1)}<small>${unit}</small></div><div class="mini">${vals.length} usable sessions · average</div></div></div>${barsChart(values,{id:'sport-history',unit})}<div class="chart-insight">${sportTrendMetric==='loadPer60'?'Garmin activity load divided by session hours. A higher value means denser recorded workload, not a measured improvement in skill.':sportTrendMetric==='highSharePct'?'Zones 4–5 minutes ÷ full session time. Missing or inconsistent zone records are left out.':'Recorded session duration. Compare a similar session length and purpose when assessing your progress.'}</div></section>`;}
function training(){const data=analyzeSport(snapshot,selectedSport,period,selectedDate);return `${pageTitle('TRAINING')}${sportPills()}<div class="two-col"><section>${sportChart(data)}<div class="detail-stat-row"><div class="detail-stat"><strong>${data.summary.sessions}</strong><span>SESSIONS</span></div><div class="detail-stat"><strong>${num(numeric(data.summary.durationMinutes)?data.summary.durationMinutes/60:null,1)}<small>h</small></strong><span>TOTAL TIME</span></div><div class="detail-stat"><strong>${num(data.summary.highMinutes)}<small>m</small></strong><span>ZONES 4–5</span></div></div><div class="insight-stack">${data.insights.slice(0,2).map(i=>insightCard(i,{click:false})).join('')}</div></section><section><div class="section-heading" style="margin-top:0"><h2>Sessions</h2><span class="pill-source">${esc(selectedSport)}</span></div><section class="card activity-card">${[...data.activities].reverse().slice(0,showAll?undefined:8).map(activityRow).join('')}${!data.activities.length?'<p class="empty-note">No workouts in this date range. Try the monthly view.</p>':''}${data.activities.length>8?`<button class="view-all" data-action="toggle-all">${showAll?'Show fewer':'View all '+data.activities.length+' sessions'}</button>`:''}</section>${data.comparison?`<div class="detail-action">${icon('target')}<div><h3>Make your next comparison count</h3><p>${data.comparison.matched.count} earlier sessions are within 20% of your latest duration. Compare the same sport, a similar session length, and your intended workout.</p></div></div>`:''}</section></div>`;}
function comparisonOptions(current){return snapshot.activities.filter(a=>(a.sportKey&&current.sportKey?a.sportKey===current.sportKey:a.type===current.type)&&Date.parse(a.date)<Date.parse(current.date)).sort((a,b)=>Date.parse(b.date)-Date.parse(a.date));}
function comparisonTable(c){if(!c.previous)return '<p class="empty-note">No earlier session in this sport is available.</p>';const a=c.currentStats,b=c.previousStats,d=c.deltas;const rows=[['Duration',num(a.durationMinutes,1)+'m',num(b.durationMinutes,1)+'m',signed(d.durationPct,'%')],['Avg. heart rate',num(a.avgHr),num(b.avgHr),signed(d.avgHr,' bpm')],['Zones 4–5',num(a.highMinutes,1)+'m',num(b.highMinutes,1)+'m',signed(d.highMinutes,'m')],['High-intensity share',num(a.highSharePct,1)+'%',num(b.highSharePct,1)+'%',signed(d.highSharePp,'pp')],['Garmin load / hour',num(a.loadPer60,1),num(b.loadPer60,1),signed(d.loadPer60Pct,'%')],['Aerobic effect',num(a.aerobicEffect,1),num(b.aerobicEffect,1),signed(d.aerobicEffect)],['Anaerobic effect',num(a.anaerobicEffect,1),num(b.anaerobicEffect,1),signed(d.anaerobicEffect)]];if(numeric(a.distanceKm)||numeric(b.distanceKm))rows.splice(1,0,['Distance',num(a.distanceKm,2)+' km',num(b.distanceKm,2)+' km',signed(d.distancePct,'%')]);if(['Run','Walking'].includes(c.current.type)&&(numeric(a.paceSecondsPerKm)||numeric(b.paceSecondsPerKm)))rows.splice(2,0,['Pace',numeric(a.paceSecondsPerKm)?hm(a.paceSecondsPerKm)+' /km':'—',numeric(b.paceSecondsPerKm)?hm(b.paceSecondsPerKm)+' /km':'—',signed(d.paceSecondsPerKm,' sec/km')]);return `<table class="comparison-table"><thead><tr><th>METRIC</th><th>LATEST</th><th>PREVIOUS</th><th>CHANGE</th></tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell.replace('—%','—').replace('—m','—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function zones(activity){const s=activityStats(activity);const floors=snapshot.zoneProfiles?.find(p=>p.sport.toLowerCase()===activity.type.toLowerCase())?.floors||snapshot.zoneBoundaries||[];const palette=['#b8cad5','#78a7c3','#438a9b','#d0bd69','#dc8075'];return `<section class="card trend-card"><div class="card-head"><div><h2>HEART RATE ZONES</h2><p>Recorded time and share of full session</p></div>${icon('activity')}</div><div class="zones">${s.zones.length?[4,3,2,1,0].map(i=>`<div class="zone-row" style="--accent:${palette[i]}"><div class="zone-top"><label>ZONE ${i+1}<small>${floors[i]?floors[i]+(floors[i+1]?'–'+(floors[i+1]-1):'+')+' bpm':''}</small><b>${numeric(s.zoneShares[i])?num(s.zoneShares[i],1)+'%':''}</b></label><span>${longTime(s.zones[i])}</span></div><div class="zone-track"><i style="width:${Math.min(100,s.zones[i]/Math.max(s.durationMinutes,1)*100)}%"></i></div></div>`).join(''):'<p class="empty-note">Zone durations were not recorded.</p>'}</div><p class="data-note">${s.zoneQuality==='inconsistent'?'Source zone totals exceed recorded duration; percentages are withheld.':s.zoneCoveragePct!=null?`${num(s.zoneCoveragePct,1)}% of session time is assigned to these zones. ${num(s.unclassifiedMinutes,1)} min is below the supplied zones or unclassified.`:'No zone coverage available.'}</p></section>`;}
function workout(){const current=snapshot.activities.find(a=>a.id===currentId&&localDate(a.date,snapshot.timezone)<=selectedDate)||day.featuredActivity;if(!current)return '<p class="empty-screen">No workout selected.</p>';currentId=current.id;const options=comparisonOptions(current);if(previousId&&!options.some(a=>a.id===previousId))previousId=null;const c=compareActivities(snapshot,currentId,previousId||undefined),s=c.currentStats;return `${pageTitle(current.type.toUpperCase(),'training')}<div class="sport-title"><span class="sport-icon">${icon(sportIcon(current.type))}</span><div><h1>${esc(current.type)}</h1><p>${dateLabel(current.date,{weekday:'short',month:'short',day:'numeric'})} · ${shortTime(current.date)} · ${esc(current.benefit.replaceAll('_',' ').toLowerCase())}</p></div></div><div class="two-col"><section>${heartChart(current)}<div class="detail-stat-row"><div class="detail-stat"><strong>${hm(s.durationMinutes)}</strong><span>DURATION · H:MM</span></div><div class="detail-stat"><strong>${num(s.avgHr)}<small>bpm</small></strong><span>AVG. HEART RATE</span></div><div class="detail-stat"><strong>${num(s.maxHr)}<small>bpm</small></strong><span>MAX. HEART RATE</span></div></div>${zones(current)}${experience.workoutExtras(current)}</section><section><section class="card"><div class="card-head"><h2>HOW THIS SESSION CHANGED</h2>${icon('trend')}</div><div class="card-body"><label class="field"><span>Compare with an earlier ${esc(current.type.toLowerCase())} session</span><select id="compare-workout">${options.length?options.map(a=>`<option value="${esc(a.id)}" ${c.previous?.id===a.id?'selected':''}>${dateLabel(a.date,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} · ${num(a.durationSec/60)} min</option>`).join(''):'<option>No earlier session</option>'}</select></label><div class="delta-grid"><div class="delta-tile"><label>High-intensity share</label><strong>${signed(c.deltas.highSharePp,'pp')}</strong><small>${valueUnit(s.highSharePct,'%')} vs ${valueUnit(c.previousStats?.highSharePct,'%')}</small></div><div class="delta-tile"><label>Training load per hour</label><strong>${signed(c.deltas.loadPer60Pct,'%')}</strong><small>Adjusted for session duration</small></div></div>${comparisonTable(c)}<p class="comparison-info" style="margin:16px 0 0">${c.previous?`Session duration ${signed(c.deltas.durationPct,'%')}. Zone coverage ${valueUnit(s.zoneCoveragePct,'%')} vs ${valueUnit(c.previousStats?.zoneCoveragePct,'%')}.`:''}</p></div></section><div class="detail-action">${icon('target')}<div><h3>${c.matched.count?c.matched.count+' similar-length sessions':'No similar-length session yet'}</h3><p>${c.matched.count?`Earlier ${current.type.toLowerCase()} sessions within ±20% of this duration. ${c.matched.limited?'This is a small comparison sample.':''}`:`The comparison window is ${num(c.matched.durationRangeMinutes?.[0])}–${num(c.matched.durationRangeMinutes?.[1])} minutes. Track a similar duration next time for a fairer comparison.`}</p></div></div><div class="insight-stack">${c.insights.map(i=>insightCard(i,{click:false})).join('')}</div><p class="subtle-note">Workload changes do not measure match performance or soccer skill. Use these alongside your session purpose and how hard it felt.</p></section></div>`;}
function insights(){return `${pageTitle('YOUR INSIGHTS')}<p class="insight-meta">${dateLabel(selectedDate,{weekday:'long',month:'long',day:'numeric'})} · based on your saved measurements</p><div class="insight-stack wide">${personalFeedback(snapshot,goals,profile,selectedDate).map(i=>insightCard(i,{click:false,label:'PERSONALIZED · CALCULATED'})).join('')}${publishedRecommendations().map(i=>insightCard(i,{click:false,label:demo()?'DEMO RECOMMENDATION':'AI · YOUR PLAN'})).join('')}${day.insights.map(i=>insightCard(i,{click:false,label:i.id.includes('sleep')?'SLEEP':i.id.includes('hrv')?'RECOVERY':day.featuredSport||'TRAINING'})).join('')}</div><button class="section-link" style="margin-top:22px" data-action="about"><span>${icon('info')}How these insights are calculated</span>${icon('chevron')}</button>`;}
function goalsView(){return `${pageTitle('MY GOALS','more')}<div class="form-panel"><div class="goal-hero"><h2>${esc(goals.primary)}</h2><p>Your targets shape the progress cards and daily analysis.</p></div><form id="goals-form"><div class="form-grid"><label class="field wide"><span>My primary goal</span><input name="primary" maxlength="80" value="${esc(goals.primary)}" required></label><label class="field"><span>Workouts per week</span><input name="workoutsPerWeek" type="number" min="1" max="14" step="1" value="${goals.workoutsPerWeek}" required></label><label class="field"><span>Sleep · hours per night</span><input name="sleepHours" type="number" min="${profile.age&&profile.age<18?8:6}" max="12" step=".25" value="${goals.sleepHours}" required></label><label class="field"><span>Weekly intensity minutes</span><input name="weeklyIntensityMinutes" type="number" min="1" max="3000" step="1" value="${goals.weeklyIntensityMinutes||150}" required></label><label class="field"><span>Time target · minutes</span><input name="targetMinutes" type="number" min="10" max="120" step=".5" value="${goals.targetMinutes}" required></label><label class="field wide"><span>Time target applies to</span><select name="targetKind"><option value="session-duration" ${goals.targetKind==='session-duration'?'selected':''}>Typical workout duration</option><option value="5k-time" ${goals.targetKind!=='session-duration'?'selected':''}>5K finish time</option></select></label><label class="field wide"><span>Weekly distance target · km</span><input name="weeklyDistanceKm" type="number" min="1" max="200" step=".5" value="${goals.weeklyDistanceKm}" required></label></div><p class="form-error" id="form-error" role="alert"></p><div class="form-actions"><button class="button-secondary" type="button" data-page="home">Cancel</button><button class="button-primary" type="submit">Save goals ${icon('check')}</button></div></form></div>`;}
function more(){return `${pageTitle('MORE')}<div class="form-panel"><div class="more-menu">${[['profile','Personal profile','Your age, height, weight, and sport','heart'],['metrics','All measurements','Every available reading, explained','activity'],['goals','My goals','Weekly training, sleep, and time targets','target'],['device','My CIRQA','Device capabilities and available data','band'],['insights','Your insights','Training, sleep, and personal baselines','spark']].map(([id,title,sub,i])=>`<button class="menu-row" data-page="${id}">${icon(i)}<div><strong>${title}</strong><small>${sub}</small></div>${icon('chevron')}</button>`).join('')}<button class="menu-row" data-action="about">${icon('info')}<div><strong>About this dashboard</strong><small>Data sources and calculation methods</small></div>${icon('chevron')}</button><button class="menu-row" data-action="connection">${icon('refresh')}<div><strong>AI connection</strong><small>Optional AI model setup</small></div>${icon('chevron')}</button></div>${refreshControl()}<p class="subtle-note">${demo()?'Demo data. Your edited goals are saved in this browser.':'Saved information opens first. New data is checked on opening and every 30 minutes while this page is visible.'}</p></div>`;}
const capabilityGroups=[['RECOVERY & TRAINING',['readiness','hrv','hrvStatus','vo2max','trainingStatus','workoutBenefit','recoveryHours']],['SLEEP & HEALTH',['heartRate','restingHr','bodyBattery','stress','sleepMinutes','sleepScore','sleepNeedMinutes','napMinutes','respiration','pulseOx','skinTemperature']],['DAILY ACTIVITY',['steps','calories','intensityMinutes']]];
function device(){return `${pageTitle('MY CIRQA','more')}<div class="goal-hero"><h2>Garmin CIRQA</h2><p>${demo()?'Demo device · not connected':'Garmin Personal API · private connection'}<br>Data through ${dateLabel(snapshot.dataThrough,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</p></div><div class="capability-layout">${capabilityGroups.map(([title,keys])=>`<section class="card capability-section"><h2>${title}</h2>${keys.map(key=>`<div class="capability-row"><strong>${metricNames[key]}</strong><span class="${snapshot.metrics[key]?.status==='available'?'':'unavailable'}">${snapshot.metrics[key]?.status==='available'?demo()?'Demo':'Available':'Not imported'}</span></div>`).join('')}</section>`).join('')}<section class="card capability-section"><h2>OTHER CAPABILITIES</h2>${[['80+ activity types','Recorded activities'],['Automatic activity detection','Source support'],['Connected GPS','Requires your phone'],['LiveTrack','Garmin Connect'],['Cycle & pregnancy tracking','Off · opt-in'],['Natural Cycles','Companion service']].map(([a,b])=>`<div class="capability-row"><strong>${a}</strong><span class="unavailable">${b}</span></div>`).join('')}</section></div><p class="subtle-note">A device feature may not be available through the Personal API. Unavailable readings stay empty. The band’s battery percentage and exact last-sync time are not exposed in this import.</p>${refreshControl()}`;}
const views={home,health,sleep,recovery,effort,stress,training,workout,insights,goals:goalsView,more,device};
const experience=createExperience({state:()=>({snapshot,goals,profile,day,selectedDate,period}),ui:{icon,esc,num,hm,longTime,dateLabel,timeLabel,shortTime,localDate,metric,colors,units,metricNames,pageTitle,dials,refreshControl,insightCard,monitors,dailyActivities,activityRow,featuredSport,planCard,trendCard,lineChart,openDialog,navigate,toast},setProfile:p=>{profile=p;if(p.preferredSport)selectedSport=p.preferredSport;}});
Object.assign(views,experience.views);

function render(){refreshDay();const focusId=document.activeElement?.id;$('#app').innerHTML=`<div class="app-shell">${experience.header()}<main id="main" tabindex="-1" class="${page==='home'?'':'page-content'}">${snapshot?views[page]?.()||home():`<div class="empty-screen">Loading your saved dashboard…</div>${refreshControl()}`}</main>${nav()}</div>`;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
function openDialog(title,body){focusBeforeDialog=document.activeElement;$('#modal').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="Close">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;$('#modal').showModal();}
function closeDialog(){$('#modal').close();focusBeforeDialog?.focus();}
function about(){openDialog('About your insights',`<p>${demo()?'This is a fictional demo dataset.':'Measurements come from your Garmin Personal API data.'} Charts use actual recorded values; gaps stay empty.</p><p>Comparisons, personal baselines, and recommendations are calculated locally from those measurements. Higher training load or more time in a high heart-rate zone is not a measured improvement in soccer skill or fitness.</p><p>Sleep is Garmin’s sleep score. Recovery displays Garmin Body Battery when training readiness is unavailable. Effort is Garmin intensity minutes. No WHOOP scores are estimated.</p><p>Feedback labeled calculated uses your measurements and profile without an AI model. Checks run on opening and every 30 minutes while visible. No background scheduler is active.</p><p class="metric-reason">Data through ${dateLabel(snapshot?.dataThrough,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}. Snapshot updated ${dateLabel(snapshot?.generatedAt,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}.</p>`);}
function metricDialog(key){const b=key==='bodyBattery'?null:day.health.metrics[key],v=metric(key),m=snapshot.metrics[key],row=day.day;const sourceTime=m?.observedAt&&localDate(m.observedAt,snapshot.timezone)===selectedDate?m.observedAt:key.startsWith('sleep')?row?.sleepObservedAt||row?.sleepEnd:key==='hrv'?row?.hrvObservedAt:row?.observedAt;openDialog(metricNames[key],`<p>${esc(experience.explanations[key]||'A recorded Garmin measurement.')}</p><div class="big-metric">${typeof v==='string'?esc(v):num(v,1)}<small>${numeric(v)?units[key]||'':''}</small></div>${numeric(v)&&b?.sufficient?`<p>Your prior ${b.count}-observation median is <strong>${num(b.baseline,1)} ${units[key]||''}</strong>. This reading is ${signed(b.delta,' '+(units[key]||''))} from that baseline.</p><p>The central 60% of your earlier observations was ${num(b.rangeLow,1)}–${num(b.rangeHigh,1)}. This describes your history, not a medical reference range.</p>`:`<p>${v==null?esc('No recorded value is available for this day.'):key==='bodyBattery'?'Latest recorded value for this day. Earlier daily values may have been measured at different times.':'Shown from the recorded source value.'}</p>`}<p class="metric-reason">${v!=null?esc(m?.sourceField||'Garmin source data'):'Selected day'} · ${dateLabel(sourceTime||selectedDate,sourceTime?{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}:{month:'short',day:'numeric'})}</p>`);}
function calendar(){if(!day?.availableDates.length)return;openDialog('Choose a day',`<p>${dateLabel(day.availableDates[0])} – ${dateLabel(day.availableDates.at(-1))} · recorded history</p><div class="calendar-grid">${day.availableDates.map(date=>`<button data-date="${date}" class="${date===selectedDate?'active':''}" aria-label="${dateLabel(date,{month:'long',day:'numeric'})}">${Number(date.slice(-2))}</button>`).join('')}</div>`);}
function connection(){experience.connection();}

let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
document.addEventListener('click',async event=>{
  const button=event.target.closest('button');if(!button)return;
  if(button.hasAttribute('data-close')){closeDialog();return;}
  if(button.dataset.page){navigate(button.dataset.page);return;}
  if(button.dataset.dateStep){const dates=day.availableDates,index=dates.indexOf(selectedDate);selectedDate=dates[index+Number(button.dataset.dateStep)]||selectedDate;currentId=null;previousId=null;render();return;}
  if(button.dataset.date){selectedDate=button.dataset.date;currentId=null;previousId=null;closeDialog();render();return;}
  if(button.dataset.period){period=Number(button.dataset.period);render();return;}
  if(button.dataset.trend){trendMetric=button.dataset.trend;render();return;}
  if(button.dataset.sportTrend){sportTrendMetric=button.dataset.sportTrend;render();return;}
  if(button.dataset.sport){selectedSport=button.dataset.sport;showAll=false;render();return;}
  if(button.dataset.openSport){selectedSport=button.dataset.openSport;period=28;navigate('training');return;}
  if(button.dataset.workout){currentId=button.dataset.workout;previousId=null;navigate('workout');return;}
  if(button.dataset.metric){metricDialog(button.dataset.metric);return;}
  if(button.dataset.insight){const insight=[...personalFeedback(snapshot,goals,profile,selectedDate),...publishedRecommendations(),...day.insights].find(i=>i.id===button.dataset.insight);if(insight)openDialog(esc(insight.title),`<p>${esc(insight.body)}</p><div class="detail-action">${icon('target')}<div><h3>Next step</h3><p>${esc(insight.action)}</p></div></div><p class="metric-reason">${insight.source==='grok'?'Grok recommendation based on your saved measurements and current goals.':demo()&&insight.source==='demo-rule'?'Illustrative recommendation using demo data.':'Calculated from your recorded data. Open the activity comparison to inspect source values and sample coverage.'}</p><button class="button-primary" data-dialog-sport="${esc(day.featuredSport||'')}">View comparison ${icon('arrow')}</button>`);return;}
  if(button.hasAttribute('data-dialog-sport')){closeDialog();currentId=day.featuredActivity?.id;previousId=null;navigate('workout');return;}
  if(button.dataset.action){const actions={about,calendar,connection,'toggle-all':()=>{showAll=!showAll;render();},'baseline-info':()=>openDialog('Your personal baseline','<p>Baselines use the median of up to 28 earlier recorded days, excluding the selected day. The observed band is the central 60% of those values and requires at least seven observations.</p><p>Historical comparisons are personal context, not medical ranges or proprietary WHOOP scores.</p>')};actions[button.dataset.action]?.();return;}
  if(button.id==='refresh'&&!refreshing){refreshing=true;render();try{const followLatest=day?.isLatestDay;const next=await refreshInsights(goals);snapshot=next;if(followLatest||!selectedDate)selectedDate=localDate(snapshot.dataThrough,snapshot.timezone);toast(demo()?'Demo insights refreshed':'Your latest available data is ready');}catch{toast('Showing your saved dashboard. Try refreshing later.');}finally{refreshing=false;render();}}
});
document.addEventListener('change',event=>{if(event.target.id==='compare-workout'){previousId=event.target.value;render();}});
document.addEventListener('submit',async event=>{if(event.target.id!=='goals-form')return;event.preventDefault();const form=event.target,submit=form.querySelector('[type=submit]');const data=new FormData(form);const next={version:goals.version+1,primary:String(data.get('primary')).trim(),targetKind:String(data.get('targetKind')),...Object.fromEntries(['workoutsPerWeek','sleepHours','weeklyIntensityMinutes','targetMinutes','weeklyDistanceKm'].map(key=>[key,Number(data.get(key))]))};submit.disabled=true;try{goals=await persistGoals(next);navigate('home');toast('Goals saved. Your analysis now uses the new targets.');}catch{$('#form-error').textContent='Unable to save. Check your targets or reload the current goals.';submit.disabled=false;}});
function chartPoint(event){const point=event.target.closest('[data-chart-point]');if(!point)return;const readout=document.getElementById('readout-'+point.dataset.readout);if(readout)readout.textContent=point.dataset.chartPoint;}
document.addEventListener('pointerover',chartPoint);document.addEventListener('pointerdown',chartPoint);document.addEventListener('focusin',chartPoint);
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const bounds=event.target.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)closeDialog();}});
$('#modal').addEventListener('close',()=>focusBeforeDialog?.focus());
const initial=location.hash.slice(1);if(initial==='overview')page='home';else if(views[initial])page=initial;render();
if(!demo())Promise.allSettled([loadLatest(),loadGoals(),loadProfile()]).then(results=>{const followingLatest=day?.isLatestDay;if(results[0].status==='fulfilled'){snapshot=results[0].value;if(followingLatest||!selectedDate)selectedDate=localDate(snapshot.dataThrough,snapshot.timezone);}if(results[1].status==='fulfilled')goals=results[1].value;if(results[2].status==='fulfilled'){profile=results[2].value;if(profile.preferredSport)selectedSport=profile.preferredSport;}render();quietCheck();});

async function quietCheck(){if(demo()||refreshing||document.visibilityState==='hidden')return;try{const following=day?.isLatestDay,next=await refreshInsights(goals,'check');if(next.id!==snapshot?.id){snapshot=next;if(following)selectedDate=localDate(next.dataThrough,next.timezone);render();}}catch{}}
setInterval(quietCheck,30*60*1000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')quietCheck();});
